src = open('main.py').read()

# insert a distance-seeded initial partition helper before moore()
helper = '''def seed_partition(n, sigma, trans, accept):
    """Initial refinement: states are separated by their distance to the
    nearest accepting state.  States at different distances can never be
    equivalent, so this is a safe refinement of the accept partition and it
    saves many refinement rounds."""
    if sigma:
        reverse = [[] for _ in range(n)]
        for q in range(n):
            for target in trans[q]:
                if target != q:
                    reverse[target].append(q)
    else:
        reverse = [[] for _ in range(n)]
    dist = [-1] * n
    queue = deque()
    for q in range(n):
        if accept[q]:
            dist[q] = 0
            queue.append(q)
    while queue:
        state = queue.popleft()
        step = dist[state] + 1
        for prev in reverse[state]:
            if dist[prev] < 0:
                dist[prev] = step
                queue.append(prev)
    numbering = {}
    part = [0] * n
    for q in range(n):
        value = dist[q]
        ident = numbering.get(value)
        if ident is None:
            ident = len(numbering)
            numbering[value] = ident
        part[q] = ident
    return part, len(numbering)


'''
src = src.replace('def moore(n, trans, part, blocks):', helper + 'def moore(n, trans, part, blocks):')

old_min_head = '''def minimize(n, sigma, trans, accept):
    """Canonical minimal DFA: (accept, next rows, distance)."""
    if n == 1:
        part = [0]
        blocks = 1
    else:
        ones = sum(accept)
        if ones == 0 or ones == n:
            part = [0] * n
            blocks = 1
        else:
            part = accept[:]
            blocks = 2
        if blocks < n:
            part, blocks, done = moore(n, trans, part, blocks)
            if not done:
                part, blocks = hopcroft(n, sigma, trans, part, blocks)
'''
new_min_head = '''def minimize(n, sigma, trans, accept):
    """Canonical minimal DFA: (accept, next rows, distance)."""
    if n == 1:
        part = [0]
        blocks = 1
    else:
        part, blocks = seed_partition(n, sigma, trans, accept)
        if blocks < n:
            part, blocks, done = moore(n, trans, part, blocks)
            if not done:
                part, blocks = hopcroft(n, sigma, trans, part, blocks)
'''
assert old_min_head in src
src = src.replace(old_min_head, new_min_head)
